        numbers.update([a, b])

    # Filter out numbers which are greater than 1 and are common divisors of at least one pair
    candidates = set()
    for number in numbers:
        if number > 1:
            for a, b in pairs:
                if a % number == 0 or b % number == 0:
                    candidates.add(number)
